    if ' ' in txt:
        return txt.split()

    odd_chars = set(chr(c) for c in range(ord('a') + 1, ord('z') + 1, 2))

    if any(c in odd_chars for c in txt):
        result, cur = [], []
        for c in txt:
            if c in odd_chars:
                if cur:
                    result.append(''.join(cur))
                    cur = []
            else:
                cur.append(c)
        if cur:
            result.append(''.join(cur))
        return result

    return sum(1 for c in txt if c.islower() and (ord(c) - ord('a')) % 2 == 1)
```

