def Strongest_Extension(class_name, extensions):
    def strength(e):
        return sum(1 for c in e if c.isupper()) - sum(1 for c in e if c.islower())

    best = extensions[0]
    best_score = strength(best)
    for e in extensions[1:]:
        s = strength(e)
        if s > best_score:
            best = e
            best_score = s
    return f"{class_name}.{best}"
```

